export function clamp(x, lo, hi) {
  if (lo > hi) throw new RangeError(`lo (${lo}) > hi (${hi})`);
  return Math.min(Math.max(x, lo), hi);
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { clamp } from "../src/clamp.mjs";

test("clamp below range", () => assert.equal(clamp(-5, 0, 10), 0));
test("clamp inside range", () => assert.equal(clamp(5, 0, 10), 5));
test("clamp above range", () => assert.equal(clamp(15, 0, 10), 10));
test("clamp at bounds", () => {
  assert.equal(clamp(0, 0, 10), 0);
  assert.equal(clamp(10, 0, 10), 10);
});
test("clamp equal bounds", () => {
  assert.equal(clamp(-1, 3, 3), 3);
  assert.equal(clamp(7, 3, 3), 3);
});
test("clamp throws RangeError when lo > hi", () =>
  assert.throws(() => clamp(5, 10, 0), RangeError));

